import { unstable_cache } from 'next/cache';
import { getAllProducts } from './db.js';

/**
 * Fetches products with cache tag for invalidation.
 * Cached to provide fast read-heavy performance.
 */
export const getCachedProducts = unstable_cache(
  async () => {
    return await getAllProducts();
  },
  ['products-data'],
  {
    tags: ['products'],
    revalidate: false // Only revalidate when explicitly invalidated
  }
);

