import { revalidateTag } from 'next/cache';
import { getCachedProducts } from '@/lib/products';

export default async function AdminCatalogPage() {
  const products = await getCachedProducts();

  async function syncCatalog() {
    'use server';

    // Simulate background sync job
    // In production, this would trigger an async job to update from ERP/PIM
    Promise.resolve().then(async () => {
      // Simulate sync delay (thousands of SKUs)
      await new Promise(resolve => setTimeout(resolve, 2000));

      // Invalidate the cache tag to refresh product data
      revalidateTag('products');
    });

    // Return immediately without blocking
  }

  return (
    <div style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <div style={{ marginBottom: '2rem' }}>
        <h1 style={{ fontSize: '2rem', fontWeight: 'bold', marginBottom: '1rem' }}>
          Admin Product Catalog
        </h1>

        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              backgroundColor: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '0.375rem',
              cursor: 'pointer',
              fontSize: '0.875rem',
              fontWeight: '500'
            }}
          >
            Sync latest catalog
          </button>
        </form>

        <p style={{ marginTop: '0.5rem', fontSize: '0.875rem', color: '#666' }}>
          Sync runs in the background. You can continue working immediately.
        </p>
      </div>

      <div style={{
        border: '1px solid #e5e7eb',
        borderRadius: '0.5rem',
        overflow: 'hidden'
      }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead style={{ backgroundColor: '#f9fafb' }}>
            <tr>
              <th style={{
                padding: '0.75rem 1rem',
                textAlign: 'left',
                fontWeight: '600',
                fontSize: '0.875rem',
                color: '#374151'
              }}>
                ID
              </th>
              <th style={{
                padding: '0.75rem 1rem',
                textAlign: 'left',
                fontWeight: '600',
                fontSize: '0.875rem',
                color: '#374151'
              }}>
                Product Name
              </th>
              <th style={{
                padding: '0.75rem 1rem',
                textAlign: 'left',
                fontWeight: '600',
                fontSize: '0.875rem',
                color: '#374151'
              }}>
                Price
              </th>
            </tr>
          </thead>
          <tbody>
            {products.map((product, index) => (
              <tr
                key={product.id}
                style={{
                  borderTop: index > 0 ? '1px solid #e5e7eb' : 'none'
                }}
              >
                <td style={{ padding: '1rem', fontSize: '0.875rem' }}>
                  {product.id}
                </td>
                <td style={{ padding: '1rem', fontSize: '0.875rem' }}>
                  {product.name}
                </td>
                <td style={{ padding: '1rem', fontSize: '0.875rem' }}>
                  ${product.price}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

